-- 2026-10-16 まさ指示: 排水事業の菌体量に連動するFAME生産量と小規模バッチ費用。データのみ、一度だけ適用。
begin;
select set_config('amd.cost_change_reason','まさ指示: 小規模の物量・設備・追加作業で燃料試算を修正',true);
do $$ begin
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_model_id)) from project_cost_models t where cost_model_id='cm_p21_fuel_260914') is distinct from 'a75ab8a0de5fd74d0df769cdd800a94b' then raise exception 'fuel data changed: project_cost_models'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_assumption_id)) from project_cost_assumptions t where cost_model_id='cm_p21_fuel_260914') is distinct from '8a27af9e0da9744062e34cc51a1ab7e0' then raise exception 'fuel data changed: project_cost_assumptions'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_item_id)) from project_cost_items t where cost_model_id='cm_p21_fuel_260914') is distinct from '053685818439103d21532bd7312a8bed' then raise exception 'fuel data changed: project_cost_items'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_task_id)) from project_cost_tasks t where cost_model_id='cm_p21_fuel_260914') is distinct from '2d1d2cc454d1776d8ac79de46b362f26' then raise exception 'fuel data changed: project_cost_tasks'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_note_id)) from project_cost_notes t where cost_model_id='cm_p21_fuel_260914') is distinct from '545be3dec2284ac19ba91ff2a082d2a6' then raise exception 'fuel data changed: project_cost_notes'; end if;
end $$;
update project_cost_assumptions set label='専用培養・在庫比較の燃料目標量',note='専用培養または在庫量からの比較で使う目標量10,000L。排水事業に連動する条件では、排水処理の菌体使用量からFAME量を出力する。',updated_at=now() where cost_assumption_id='caf_business_annual_volume';
update project_cost_assumptions set value=20000,note='小規模の脂肪酸回収設備1系列: 分泌脂肪酸換算100kg/回×年200回＝20,000kg/年を仮置き。酸析200万円・受槽送液50万円・付帯100万円・保管出荷50万円の設備構成。接触回収と溶媒在庫は別の培養追加設備で数える。対象株・溶媒の条件による能力は要検証。',confidence='H',source_kind='仮置き',updated_at=now() where cost_assumption_id='caf_plant_line_capacity_secreting';
update project_cost_assumptions set label='燃料化設備1系列の総額上書き（任意）',note='空欄は設備明細の積上げ額を使う。小規模の分泌回収は400万円、自社FAME転換を含めると900万円の内部概算。上書き時は選んだ設備構成と保守費を同率変更する。見積取得前。',updated_at=now() where cost_assumption_id='caf_op_fuel_plant_capex_override';
update project_cost_assumptions set value=1000,label='製品1便の出荷量',note='小規模の製品出荷は1,000L/便を仮置き。容器入り製品を運ぶ費用と荷役は作業欄で計上する。運送会社の見積取得前。',updated_at=now() where cost_assumption_id='caf_truck_capacity';
update project_cost_assumptions set value=1000,note='品質確認は製品1,000Lを1ロットとする仮置き。年10,000Lでは10回。1回15万円＋採取記録2時間を数える。契約する分析項目とロット条件を見積で更新する。',updated_at=now() where cost_assumption_id='caf_lot_size';
update project_cost_items set unit_price=2000000,useful_life_years=7,confidence='H',source_kind='仮置き',note='2026-10-16 小規模バッチの内部概算、見積取得前。加温・酸析槽120万円＋デカンター・中和80万円。分泌脂肪酸換算100kg/回・年200回を想定。培養液との接触・溶媒在庫・閉鎖系は培養側の追加設備。材質・防爆・油水分離性能・工事費を含む供給者見積で更新する。',updated_at=now() where cost_item_id='cif_sec_plant_strip';
update project_cost_items set unit_price=500000,useful_life_years=7,confidence='H',source_kind='仮置き',note='2026-10-16 小規模バッチの内部概算、見積取得前。濃縮液受槽25万円＋移送ポンプ・配管25万円。分泌脂肪酸換算100kg/回・年200回を想定。培養液との接触・溶媒在庫・閉鎖系は培養側の追加設備。材質・防爆・油水分離性能・工事費を含む供給者見積で更新する。',updated_at=now() where cost_item_id='cif_sec_plant_solvent';
update project_cost_items set unit_price=1000000,useful_life_years=7,confidence='H',source_kind='仮置き',note='2026-10-16 小規模バッチの内部概算、見積取得前。配管・計装50万円＋電気・据付・排水接続50万円。分泌脂肪酸換算100kg/回・年200回を想定。培養液との接触・溶媒在庫・閉鎖系は培養側の追加設備。材質・防爆・油水分離性能・工事費を含む供給者見積で更新する。',updated_at=now() where cost_item_id='cif_sec_plant_utility';
update project_cost_items set strain='wild',updated_at=now() where cost_item_id='cif_ship_tank';
update project_cost_items set strain='wild',updated_at=now() where cost_item_id='cif_in_capex';
update project_cost_items set strain='wild',updated_at=now() where cost_item_id='cif_in_maintenance';
update project_cost_items set unit_price=120000,confidence='H',source_kind='仮置き',note='分泌回収の小規模設備400万円（酸析200万円＋受槽50万円＋付帯100万円＋保管出荷50万円）×3%/年。初期投資額に連動。保守見積取得前。',updated_at=now() where cost_item_id='cif_sec_op_maintenance';
update project_cost_items set unit_price=20,confidence='H',source_kind='仮置き',note='委託先への原料油輸送を小口1,000L×2万円/便相当の20円/Lとして仮置き。見積取得前。製品の出荷費は別。',updated_at=now() where cost_item_id='cif_out_transport';
update project_cost_tasks set label='分泌回収ループの追加点検（1日分）',hours_per_occurrence=0.25,confidence='H',source_kind='仮置き',note='同時利用培養液222.22m³相当の接触回収1系列につき1日15分×300日を仮置き。溶媒相・ポンプ・漏れ・菌体への影響の追加確認。共通培養管理は配賦欄で扱う。点検実測前。',updated_at=now() where cost_task_id='ctf_sec_culture_operation';
update project_cost_tasks set label='濃縮液から脂肪酸を回収（製造1回）',hours_per_occurrence=2,count_driver='batch',count_per_year=null,confidence='H',source_kind='仮置き',note='100kg-分泌脂肪酸換算につき投入・酸析の操作0.5時間＋分離確認・抜出し0.5時間＋洗浄・記録1時間＝2人時を仮置き。年間回数は必要量÷製造1回の処理量を切上げ。反応待ち時間と人が作業する時間を区別し、実測で更新する。',updated_at=now() where cost_task_id='ctf_sec_plant_operation';
update project_cost_tasks set strain='wild',updated_at=now() where cost_task_id='ctf_inhouse_operation';
update project_cost_tasks set label='容器入り製品の出荷（1便）',hours_per_occurrence=1,expense_per_occurrence=20000,confidence='H',source_kind='仮置き',note='小規模の製品1,000L/便。運賃2万円＋荷役記録1時間を仮置き。運送見積取得前。',updated_at=now() where cost_task_id='ctf_ship_truck';
update project_cost_notes set title='排水処理の菌体量から年間FAME生産量を見る',body_md='最初は排水処理で使う年間の新しい菌体量に連動する。排水側の保存前の試算・用途・株の選択も、燃料へ切り替えた際に反映する。生産量は計算結果として表示し、排水処理の条件を変更して比較する。「在庫から算定」へ切り替えると入力在庫を使う。光源と出荷待ち/専用培養を切り替え、必要培養液・追加設備・製造回数・年額費用を比較する。設備と作業は小規模の内部仮置き。各行の内訳を開き、見積・実測で更新する。' where cost_note_id='cnf_guide';
update project_cost_notes set title='小規模設備と追加作業の前提',body_md='分泌回収の燃料化設備は酸析200万円・受槽送液50万円・付帯100万円・保管出荷50万円＝400万円、耐用7年の内部概算。分泌脂肪酸換算100kg/回・年200回の能力を仮置き。回収は2人時/回、接触回収ループの点検は222.22m³相当の1系列につき15分/日。培養液への接触装置・溶媒初期充填・閉鎖系管理は培養追加設備として別計上する。費用・能力・工数は見積取得・実測で更新する。' where cost_note_id='cnf_caveat_biomass';
update project_cost_notes set title='必要な在庫と太陽光の前提',body_md='太陽光の年間生産性50%、1回の待ち3日・年100回は比較用の仮定。排水処理側で年に使う菌体量を参照し、培養液の菌体濃度1kg/m³・出荷前の回収対象割合100%・待ち3日を仮置きする。稼働日内の均等出荷を仮置きし、平均在庫量で設備を数える。在庫からの算定に切り替えると10m³の操作例で年52.5L。実在庫・温度・受光面積・分泌回収量・出荷品質を測定して更新する。太陽光設備・敷地・追加維持・出荷影響の費用は追加欄で入力する。' where cost_note_id='cnf_caveat_secreting';
update project_cost_models set version_label='261016 排水事業連動・小規模バッチ',summary_md='排水処理事業の年間処理量と菌体使用量を起点に、出荷前の分泌回収で年に生産できるFAMEの数量と原価を計算する。光源と出荷待ち回収/専用培養を切り替えて比較する。分泌回収の燃料化設備は400万円、自社転換追加500万円の内部概算。物量に応じた追加回収設備、製造回数、点検、品質確認と出荷を積み上げる。各金額・工数は見積・実測で更新する。',system_scope_md='分泌株のFAME製造を、小規模バッチ回収と委託/自社転換で比較する。太陽光はLED費用を除き年間生産性比率を適用する。出荷待ち回収の共通培養費は年額配賦、溶媒・接触回収・閉鎖系・追加点検は必要な培養液量に合わせて計上する。排水事業連動では、選択用途のオンサイト・オフサイトで年に使う新しい菌体量から、濃度・待ち日数・回収対象割合・分泌速度・太陽光比率・工程収率を使って年間FAME量を計算する。稼働日内の均等出荷を仮置きし、平均の出荷待ち在庫量から追加回収設備を数える。在庫量から算定する比較も可能。屋外化・追加維持・出荷影響は入力費用で加算する。',updated_at=now() where cost_model_id='cm_p21_fuel_260914';
insert into project_cost_assumptions (code,note,unit,label,owner,value,is_key,strain,role_key,confidence,sort_order,value_text,visibility,application,group_label,source_kind,cost_model_id,cost_assumption_id) values (null,'排水処理側で選択した用途・株の年間処理量と菌体使用量から、年間の新規菌体量を参照する。菌体量÷出荷待ち培養液の菌体濃度×待ち日数×回収対象割合×分泌速度×年間生産性比率から年間の脂肪酸量を出す。在庫量から算定する比較も可能。','','生産量の決め方','AMD（内部）',null,true,null,'inventory_sizing','H',114,'effluent','amd_internal',null,'小規模の生産設計','仮置き','cm_p21_fuel_260914','caf_small_inventory_sizing');
insert into project_cost_assumptions (code,note,unit,label,owner,value,is_key,strain,role_key,confidence,sort_order,value_text,visibility,application,group_label,source_kind,cost_model_id,cost_assumption_id) values (null,'1g-DCW/L＝1kg/m³を比較用に仮置き。排水処理で使う年間の新規菌体kgを出荷前の液量へ換算する。対象株の分泌速度を測ったときの濃度と揃えて実測する。','kg-乾燥/m³','出荷待ち培養液の菌体濃度','AMD（内部）',1,true,null,'inventory_biomass_concentration','H',116,null,'amd_internal',null,'小規模の生産設計','仮置き','cm_p21_fuel_260914','caf_small_inventory_biomass_concentration');
insert into project_cost_assumptions (code,note,unit,label,owner,value,is_key,strain,role_key,confidence,sort_order,value_text,visibility,application,group_label,source_kind,cost_model_id,cost_assumption_id) values (null,'排水処理に使う新しい菌体のうち、出荷前に分泌回収へ使う割合。100%を比較用に仮置き。出荷日・品質を維持できる量を測って更新する。','%','出荷前に分泌回収へ使える菌体の割合','AMD（内部）',100,true,null,'inventory_recovery_share','H',117,null,'amd_internal',null,'小規模の生産設計','仮置き','cm_p21_fuel_260914','caf_small_inventory_recovery_share');
insert into project_cost_assumptions (code,note,unit,label,owner,value,is_key,strain,role_key,confidence,sort_order,value_text,visibility,application,group_label,source_kind,cost_model_id,cost_assumption_id) values (null,'脂質分泌株の燃料化は100kg/回、年200回までの小規模バッチ設備を想定。酸析200万円・受槽送液50万円・付帯100万円・保管出荷50万円を積上げた内部概算。見積取得前。培養液との接触・溶媒・閉鎖系は培養側の追加明細。','','設備費の前提','AMD（内部）',null,true,null,'fuel_equipment_basis','H',115,'small_batch','amd_internal',null,'小規模の生産設計','仮置き','cm_p21_fuel_260914','caf_small_fuel_equipment_basis');
insert into project_cost_assumptions (code,note,unit,label,owner,value,is_key,strain,role_key,confidence,sort_order,value_text,visibility,application,group_label,source_kind,cost_model_id,cost_assumption_id) values (null,'分泌した脂肪酸換算100kgごとに、回収・製造の作業を1回行う仮置き。年間回数は必要脂肪酸kg/年÷100kgを切上げる。品質確認ロットとは別に数える。設備能力20,000kg/年は100kg×200回。油の質・作業時間・受槽の滞留量を実測して更新する。','kg/回','回収・製造1回の処理量（脂肪酸換算）','AMD（内部）',100,true,null,'fuel_production_batch_kg','H',212,null,'amd_internal',null,'小規模の生産設計','仮置き','cm_p21_fuel_260914','caf_small_fuel_production_batch_kg');
